<script>
import NewsCard from '@/components/NewsCard/index.vue'

export default {
  name: 'FindNews',
  components: { NewsCard },
  data () {
    return {
      searchQuery: ''
    }
  },
  computed: {
    posts () {
      return this.$store.state.houseDetail.map((house, index) => ({
        id: house.id || Date.now() + index,
        image: house.pic_link || 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80',
        title: house.title || '优质房源',
        description: house.description || '暂无详细描述',
        room: house.room || '',
        building: house.building || '',
        address: house.address || '',
        price: house.price || '面议',
        contact: house.contact || '未知',
        tag: house.tag || '',
        author: house.publisher || '匿名用户',
        likes: Math.floor(Math.random() * 400) + 50,
        comments: Math.floor(Math.random() * 80) + 10
      }))
    }
  },
  methods: {
    handleSearch () {
      console.log('搜索关键词：', this.searchQuery)
    },
    temp (post) {
      console.log('点击了卡片：', post)
      this.$notify.warning({
        title: '提示',
        message: '功能开发中...',
        duration: 2000,
        position: 'top-right',
        offset: 80
      })
    }
  },
  mounted () {
    if (this.$store.state.houseDetail.length === 0) {
      this.$store.dispatch('loadHouseData')
    }
  }
}
</script>

<template>
  <div class="find-news">
    <!-- 顶部搜索框 -->
    <div class="search-wrapper">
      <el-input
        v-model="searchQuery"
        placeholder="搜索房源、帖子或用户..."
        clearable
        size="large"
        class="modern-search"
        @keyup.enter.native="handleSearch"
      >
        <template #prefix>
          <i class="el-icon-search search-icon"></i>
        </template>
        <template #append>
          <el-button type="primary" @click="handleSearch">
            <i class="el-icon-search"></i> 搜索
          </el-button>
        </template>
      </el-input>
    </div>

    <div class="posts-grid">
      <news-card
        v-for="(post, index) in posts"
        :key="post.id"
        :post="post"
        :index="index"
        @click="temp(post)"
      />
    </div>

    <!-- 空状态 -->
    <div v-if="posts.length === 0" class="empty-state">
      <el-empty description="暂无房源帖子，试试搜索其他关键词吧～"/>
    </div>
  </div>
</template>

<style scoped lang="less">
.find-news {
  min-height: 100vh;
  background: #fafafa;
  padding: 10px 10px 10px;
  box-sizing: border-box;
}

.search-wrapper {
  max-width: 80%;
  margin: 10px auto 20px;

  .modern-search {
    height: 60px;
    border-radius: 30px;
    overflow: hidden;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.08);
    transition: all 0.4s ease;

    &:hover {
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.12);
    }

    /deep/ .el-input__inner {
      height: 60px;
      line-height: 60px;
      border: none;
      font-size: 17px;
      padding-left: 60px;
    }

    .search-icon {
      font-size: 20px;
      color: #999;
      position: absolute;
      left: 22px;
      top: 50%;
      transform: translateY(-50%);
    }

    /deep/ .el-input-group__append {
      border: none;
      padding: 0 20px 0 30px ;

      .el-button {
        color: white;
        font-weight: 600;
        font-size: 16px;
        height: 100%;
        border: none;
        background: transparent;
      }
    }
  }
}

.posts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.empty-state {
  text-align: center;
  margin-top: 100px;
}
</style>
