<script>
import { mapState } from 'vuex'

export default {
  name: 'ExchangeSquare',
  data () {
    return {
      activeMenu: 'FindNews'
    }
  },
  computed: {
    ...mapState(['houseDetail'])
  },
  watch: {
    $route: {
      immediate: true,
      handler (route) {
        const path = route.path
        if (path.startsWith('/ExchangeSquare/')) {
          const routeName = path.split('/').pop()
          this.activeMenu = routeName
        }
      }
    }
  },
  methods: {
    handleMenuSelect (key) {
      this.$router.push(`/ExchangeSquare/${key}`)
    }
  }
}
</script>

<template>
  <div class="community-vitality">
    <div class="sidebar">
      <el-menu
        :default-active="activeMenu"
        class="el-menu-vertical"
        @select="handleMenuSelect"
        background-color="rgba(255, 255, 255, 0.95)"
        text-color="#2c3e50"
        active-text-color="#ffd04b"
      >
        <el-menu-item index="FindNews">
          <i class="el-icon-search"></i>
          <span slot="title">发现内容</span>
        </el-menu-item>
        <el-menu-item index="PublishContent">
          <i class="el-icon-edit"></i>
          <span slot="title">发布帖子</span>
        </el-menu-item>
        <el-menu-item index="PersonalHomepage">
          <i class="el-icon-user"></i>
          <span slot="title">个人主页</span>
        </el-menu-item>
      </el-menu>
    </div>
    <div class="content">
      <router-view/>
    </div>
  </div>
</template>

<style scoped lang="less">
.community-vitality {
  width: 100%;
  min-height: 100vh;
  display: flex;
  position: relative;
  border-radius: 15px;
  overflow: hidden;
  box-sizing: border-box;
  overflow-y: auto;
}

.sidebar {
  width: 200px;
  min-height: 100%;
  border-right: 1px solid #f0f0f0;
  padding: 20px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 2px 0 8px rgba(0, 0, 0, 0.05);

  .el-menu {
    border-right: none;
  }

  .el-menu-item {
    padding: 0 20px;
    font-size: 16px;
    font-weight: 500;
    transition: all 0.3s ease;

    i {
      margin-right: 10px;
      font-size: 18px;
    }

    &:hover {
      background: rgba(255, 208, 75, 0.1);
    }

    &.is-active {
      background: rgba(255, 208, 75, 0.2);
      border-left: 4px solid #ffd04b;
    }
  }
}

.content {
  flex: 1;
  padding: 20px;
  overflow-y: auto;
  display: flex;
  flex-wrap: wrap;
  border-radius: 0 15px 15px 0;
  gap: 20px;

  &::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  &::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 10px;
    margin: 2px;
  }

  &::-webkit-scrollbar-thumb {
    background: linear-gradient(135deg, #ffd04b, #ffb347);
    border-radius: 10px;
    border: 2px solid #f1f1f1;
  }

  &::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(135deg, #ffb347, #ff9847);
  }

  scrollbar-width: thin;
  scrollbar-color: #ffd04b #f1f1f1;
}
</style>
